from pathlib import Path
import json,html,re
from 生成说明网页 import generate as generate_reading_pages, LINKS
ROOT=Path(__file__).resolve().parent
cds=json.loads((ROOT/'CDS_重点议题榜.json').read_text());ada=json.loads((ROOT/'ADA_重点议题榜.json').read_text())
def span(r):return str(min(r['scenario_ranks'].values()))+'—'+str(max(r['scenario_ranks'].values()))
lines=['---','title: "CDS与ADA重点议题榜｜量化试评"','created: 2026-11-16','status: 待导师与专业复核；未接入正式网站','---','\n# 重点议题榜｜v0.1', '\n本轮完成两套分开解释的试评：CDS是会前日程关注度，ADA是当前候选池中的会议关联研究重要性。分数由AI按试行规则计算/判断，待导师校准，不跨会议比较，也不表示已经确认升温。', '\n[打开交互榜单](重点议题榜_待复核.html) · [完整口径](量化口径_v0.1.md) · [来源与缺口](来源覆盖与缺口.json)', '\n## 已取得什么材料', '\n- CDS：新取得官方完整日程HTML，解析148个专题、797条行、699个编号条目；600条学术报告归入12个主题。全部仍为会前计划，未取得本届结果。', '- ADA：基于原27条候选，新取得14篇原始论文完整摘要，归为7个主题；另13条保留待评估。正式论文包含会前及会后版本，未阅读全文。官方程序用于核对议题归属。', '- 评分、原始依据和缺口另存，本地正式数据、网页、GitHub和定时任务均未变。', '\n## CDS：会前关注度', '\nPI会内角色代理40＋重点报告25＋口头摘要候选量20＋专题覆盖15。PI角色代理并非独立的学术影响力评分；OR数量也不是已确认的独立研究数。', '\n|序位|议题|分数/100|大会/专题/口头报告|专题数|权重情景名次范围|', '|---:|---|---:|---|---:|---|']
for r in cds['rows']:lines.append(f"|{r['rank']}|{r['name']}|{r['score']:.1f}|{r['kinds'].get('大会报告',0)}/{r['kinds'].get('专题报告',0)}/{r['unique_or_count']}|{r['session_count']}|{span(r)}|")
lines+=['\nCDS首两项在已测权重下次序未变，但分差较小，宜按首梯队讨论；分组变化的影响仍需复核。主题是本试评的工作分组，非官方热点排行。全部逐报告归属、校正与原始链接见[分类明细CSV](CDS_报告分类明细.csv)；[分项CSV](CDS_重点议题榜.csv)。', '\n## ADA：会议关联研究重要性', '\n新颖性30＋临床科研价值35＋证据成熟度25＋多研究支持10。每项0—4分，折算后相加；公司关系不入总分。', '\n|序位|议题|分数/100|已读去重研究|主要意义与缺口|', '|---:|---|---:|---:|---|']
for r in ada['rows']:lines.append(f"|{r['rank']}|{r['name']}|{r['score']:.1f}|{r['study_count']}|{r['summary']} {('存在勘误待核，证据分已暂降。' if r.get('correction_pmids') else '')}|")
lines+=['\nCagriSema与Survodutide两组因勘误内容尚未取得，证据成熟度暂给2；若后续核清且不影响主要结论，情景总分分别为75.0与72.5。该范围表示缺口处理会影响排序，不表示结果必然正确。', '\n纵向蛋白组分数较低反映其仍处发现阶段；它与Biomarker业务更直接相关，值得优先深读，不应被药物研究榜单淹没。原站未取得完整结果的免疫分型、EV蛋白和肾内单细胞等13条线索不计0分，列入[待评估清单](ADA_待评估记录.csv)。', '\n## 与吉因加业务相关的下一步', '\n|优先复核方向|现有锚点|下一步要回答什么|', '|---|---|---|', '|早识别、分型与预测|CDS S_074、S_147、OR_031等日程；ADA A01/R03原始摘要|能否锁定具体用途和指标组合，并证明相对临床模型的增量？|', '|DKD隐匿损伤和器官风险|CDS OR_003、OR_006、OR_008、OR_143等计划|取得结果后，确认人群、样本、独立验证及组学路径；尿液、血浆和组织分别判断。|', '|T1D免疫/EV及细胞状态|CDS S_029/S_030；ADA A02/A19/A20/A21尚有原始结果缺口|先取原始结果，再评免疫分层、功能终点与标志物成熟度。|', '\n以上为研究参与建议，沿用11/10能力表中的确认范围；cfRNA、甲基化、免疫组库细项和具体交付仍待公司核对。国际榜不计算产品分。本轮尚不足以确认一个可直接进入临床的新检测标志物。', '\n## 需要导师校准的三个决定', '\n1. 国内是否接受“本届角色”作为PI临时代理？是否引入经核实的学术任职/代表工作？', '2. 12个CDS主题与7个ADA主题的颗粒度是否合适？将分组拆细后，排名是否仍有业务意义？', '3. 新颖性、临床价值和证据成熟度的权重是否符合业务？材料缺失和勘误的暂缓/降分规则如何确定？', '\n校准后再决定接入正式网站；下一轮优先补原始摘要、勘误与CDS会后结果。']
(ROOT/'重点议题榜_简版.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
# A readable evidence index, without duplicating full abstracts in the report.
source=['# 原始材料索引与读取范围','\n核对日期：2026-11-16。下面论文均读到PubMed中的原始完整摘要，未全文精读；程序PDF只作议题关联，不代替结果。','\n|主题|记录|第一作者|原始论文/摘要|在线日期（可核者）|程序物理页|勘误|','|---|---|---|---|---|---|']
for r in ada['rows']:
 for e in r['evidence']:
  source.append(f"|{r['name']}|{e['record_id']}|{e['first_author']}|[PMID {e['pmid']}]({e['url']})；DOI {e['doi']}|{','.join(e['online_dates']) or '未从ArticleDate取得，保留待核'}|{','.join(map(str,e['program_physical_pages'])) or '名称关系待核'}|{'; '.join(x['type']+':'+str(x['pmid']) for x in e['corrections'] if x['type']=='ErratumIn') or '本次元数据未标出'}|")
source+=['\n- [CDS官方详细日程](https://cds26.tiemeeting.com/CN/Program/Details)：保存HTML并逐行解析；与11/11相比OR_219不再出现。','- [ADA官方程序PDF](https://professional.diabetes.org/sites/dpro/files/2026-04/SS26_Program_Final_Digital.pdf)：使用已有4/24导出存档；物理294页已视觉核对。','- [ADA官方临床试验报道目录](https://www.adameetingnews.org/category/scientific-sessions/2026/clinical-trials-2026/)：用于复核议题背景，不算独立研究或原始结果替身。','- [REIMAGINE 2勘误索引](https://pubmed.ncbi.nlm.nih.gov/42320507/)与[SYNCHRONIZE-MASLD勘误索引](https://pubmed.ncbi.nlm.nih.gov/42642663/)：存在已核，勘误内容本轮待取得。','\n详见[机器可读覆盖与缺口](来源覆盖与缺口.json)。原始HTTP响应及XML保存于本目录“原始材料”，旧研究数据不改。']
(ROOT/'原始材料索引.md').write_text('\n'.join(source)+'\n',encoding='utf-8')
# Only evidence metadata is embedded in the dashboard; full abstracts remain in raw files.
for r in ada['rows']:
 for e in r['evidence']:e.pop('abstract',None)
data=json.dumps({'cds':cds,'ada':ada},ensure_ascii=False).replace('</','<\\/')
template='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CDS × ADA重点议题榜｜待复核</title><style>
:root{--blue:#24578e;--navy:#142b49;--ink:#172b4d;--muted:#647b98;--line:#d6e0ed;--soft:#edf3fb}*{box-sizing:border-box}body{margin:0;background:#f1f4f8;color:var(--ink);font:15px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft Yahei",sans-serif}header{background:var(--navy);color:white;padding:26px max(24px,calc((100vw - 1200px)/2))}header small{color:#c8d7ec}h1{font-size:26px;line-height:1.5;margin:5px 0}h2{font-size:18px;margin:0}p{margin:8px 0}main{max-width:1248px;margin:auto;padding:24px}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.panel{background:white;border:1px solid var(--line);border-radius:8px;padding:22px;margin-bottom:20px}.meta{font-size:13px;color:var(--muted)}.nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}button,select{font:inherit}button{background:white;border:1px solid var(--line);color:var(--blue);padding:8px 18px;border-radius:5px;cursor:pointer}button.active{background:var(--blue);color:white}.toolbar{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:center}.toolbar select{border:1px solid var(--line);border-radius:4px;padding:7px}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:18px}.stat{background:var(--soft);border-radius:5px;padding:14px}.stat b{font-size:22px;display:block}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:720px;font-size:14px;margin-top:15px}th,td{text-align:left;padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#f7f9fc;color:var(--muted);font-size:13px;font-weight:600}td.score{color:var(--blue);font-weight:700;white-space:nowrap}.bar{height:5px;background:#dce9f7;width:90px;border-radius:3px;margin-top:4px}.bar i{display:block;height:100%;background:#4479af;border-radius:3px}details{border-top:1px solid var(--line);padding:14px 0}summary{cursor:pointer;color:var(--blue);font-weight:600}ul{padding-left:22px}.pill{background:var(--soft);color:var(--blue);font-size:12px;border-radius:3px;padding:2px 6px;margin-right:5px}.warn{background:#fff5e7;padding:12px 16px;border-radius:5px;color:#815923;margin:12px 0}.links{display:flex;gap:16px;flex-wrap:wrap;margin-top:10px}footer{padding:20px;text-align:center;color:var(--muted);font-size:13px}@media(max-width:650px){header{padding:22px 18px}h1{font-size:23px}main{padding:16px}.panel{padding:16px}.stats{grid-template-columns:1fr}.stat b{display:inline;margin-right:10px}.toolbar label{width:100%}}
</style></head><body><header><small>临床科研热点工作台 · 本地试评</small><h1>CDS × ADA 重点议题榜</h1><div>2026.11.16 · v0.1 · 待导师与专业复核</div></header><main><section class="panel"><h2>把优先级和判断依据一起展示</h2><p>CDS看会前关注度，ADA看当前候选池中的研究进展重要性。两套分数分别解释；公司参与建议单列。</p><div class="links"><a href="重点议题榜_简版.md">简版报告 →</a><a href="量化口径_v0.1.md">完整评分口径 →</a><a href="原始材料索引.md">原始材料与缺口 →</a></div></section><nav class="nav" aria-label="榜单"><button data-tab="cds" class="active">CDS 会前关注度</button><button data-tab="ada">ADA 研究进展</button><button data-tab="pending">待评估与来源缺口</button></nav><section class="panel" id="view"></section><section class="panel"><h2>业务优先深读</h2><p>早识别与分型、DKD隐匿损伤、纵向蛋白标志物及T1D免疫/EV线索，可优先形成具体临床问题与验证计划。研究量大、分数高的药物进展与可参与的检测机会分别判断。</p><p class="meta">沿用11/10公司能力底表。具体样本、版本与交付范围待核；国际榜未计算产品或KOL分。本轮尚不足以确认可直接进入临床的新检测标志物。</p></section></main><footer>独立试评预览 · 正式网站未修改 · 未发布GitHub · 未设置定时任务</footer><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#data').textContent);let tab='cds',scenario='默认';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const variants={cds:{'默认':[40,25,20,15],'等权':[25,25,25,25],'PI较低':[30,25,25,20],'PI较高':[50,20,15,15]},ada:{'默认':[30,35,25,10],'等权':[25,25,25,25],'偏临床':[20,45,25,10],'偏证据':[25,30,35,10]}};
function details(r,kind){return `<details><summary>${esc(r.name)} · 分项、原始依据与业务参与</summary>${kind==='cds'?`<p>${esc(r.participation)}</p><p class="meta">${esc(r.fit_status)} · 能力表 ${r.capability_ids.map(esc).join('、')}</p><p>会内角色最高的代表讲者：${r.top_people.map(p=>`${esc(p.name)}（${esc(p.institution)}；${esc(p.role_basis.kind)} ${esc(p.role_basis.code)}）`).join('；')}</p><p>分项：${Object.entries(r.components).map(([k,v])=>esc(k)+' '+v).join(' · ')}</p><ul>${r.examples.map(x=>`<li><a href="${esc(x.source_url)}" target="_blank" rel="noopener">${esc(x.code)} · ${esc(x.title)}</a><span class="meta"> · ${esc(x.date)} · ${esc(x.kind)}</span></li>`).join('')}</ul><p class="meta">${r.gaps.map(esc).join(' ')}</p>`:`<p>${esc(r.summary)}</p><ol>${r.reasons.map((x,i)=>`<li>${esc(Object.keys(D.ada.weights)[i])} ${r.scores[i]}/4：${esc(x)}</li>`).join('')}</ol><p><b>待补：</b>${esc(r.gap)}</p>${r.score_if_correction_resolved?`<p class="warn">勘误内容待核；若核清且不影响结果，证据分可由2恢复3，对应情景总分${r.score_if_correction_resolved.toFixed(1)}。当前不预设勘误影响。</p>`:''}<p><b>业务参与：</b>${esc(r.business)}</p><p class="meta">${esc(r.fit_status)}</p><ul>${r.evidence.map(e=>`<li><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.record_id)} · PMID ${esc(e.pmid)} · ${esc(e.first_author)}</a><br><span class="meta">${esc(e.title)}<br>在线日期：${esc(e.online_dates.join('、')||'待核')} · 程序物理页：${esc(e.program_physical_pages.join('、')||'待核')} · 原始摘要，未全文</span></li>`).join('')}</ul>`}</details>`}
function render(){const v=document.querySelector('#view');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='pending'){v.innerHTML=`<h2>13条ADA记录暂不计分</h2><p>原始完整结果本轮尚未取得；不能将信息缺失当成0分。会后官方报道与旧检索索引保留作线索。</p><div class="scroll"><table><thead><tr><th>记录</th><th>研究线索</th><th>现有读取层次</th><th>原始入口</th></tr></thead><tbody>${D.ada.pending.map(r=>`<tr><td>${esc(r.id)} / ${esc(r.code)}</td><td>${esc(r.name)}</td><td>${esc(r.reading_level)}</td><td><a target="_blank" rel="noopener" href="${esc(r.official_url)}">查看来源 ↗</a></td></tr>`).join('')}</tbody></table></div><div class="warn">CDS会后结果仍待取得；PI真实学术影响、OR跨题同研究关系待核。ADA两篇原始论文存在勘误，内容待核，相关主题证据分已暂降。</div><div class="links"><a href="来源覆盖与缺口.json">完整来源审计 →</a><a href="CDS_报告分类明细.csv">CDS逐报告归类 →</a><a href="ADA_待评估记录.csv">待评估CSV →</a></div>`;return}const data=D[tab],weights=variants[tab][scenario]||variants[tab]['默认'];const rows=data.rows.map(r=>({...r,shownScore:tab==='cds'?r.components_raw.reduce((s,x,i)=>s+x*weights[i],0):r.scores.reduce((s,x,i)=>s+x*weights[i]/4,0)})).sort((a,b)=>b.shownScore-a.shownScore||a.id.localeCompare(b.id));v.innerHTML=`<div class="toolbar"><div><h2>${tab==='cds'?'CDS 2026 · 会前关注度':'ADA 2026 · 研究进展重要性'}</h2><div class="meta">${tab==='cds'?'本届角色与日程覆盖的相对分，不是研究结果强度':'已有27条候选中14条可读原始论文摘要，非全大会排名'}</div></div><label>权重情景 <select id="scenario">${Object.keys(variants[tab]).map(k=>`<option ${k===scenario?'selected':''}>${k}</option>`).join('')}</select></label></div><div class="stats">${(tab==='cds'?[[600,'条已归类学术报告'],[12,'个工作主题'],[0,'条本届结果已读']]:[[14,'篇原始论文摘要'],[7,'个试评主题'],[13,'条材料待补记录']]).map(([n,s])=>`<div class="stat"><b>${n}</b><span>${s}</span></div>`).join('')}</div><p class="meta">分项权重：${Object.keys(data.weights).map((k,i)=>esc(k)+' '+weights[i]).join(' · ')}。下表“名次范围”来自各权重情景，不是统计置信区间。</p><div class="scroll"><table><thead><tr><th>序位</th><th>议题</th><th>相对分/100</th>${tab==='cds'?'<th>大会/专题/口头</th><th>讲者/专题</th>':'<th>研究数量</th><th>原始记录</th>'}<th>名次范围</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><a href="#${r.id}">${esc(r.name)}</a>${r.correction_pmids?'<br><span class="pill">勘误内容待核</span>':''}</td><td class="score">${r.shownScore.toFixed(1)}<div class="bar"><i style="width:${r.shownScore}%"></i></div></td>${tab==='cds'?`<td>${r.kinds['大会报告']||0}/${r.kinds['专题报告']||0}/${r.unique_or_count}</td><td>${r.unique_speakers}/${r.session_count}</td>`:`<td>${r.study_count}</td><td>${r.records.join('、')}</td>`}<td>${Math.min(...Object.values(r.scenario_ranks))}—${Math.max(...Object.values(r.scenario_ranks))}</td></tr>`).join('')}</tbody></table></div><p class="meta">${tab==='cds'?'600条归类报告之外：3条标题过泛待分类、3条科研培训单列、93条专题会发言不计本套分。':'同研究版本去重；A01/R03合并。证据读取成熟度最高3/4，所有分项仍待专业校准。'}</p><div class="links"><a href="${tab==='cds'?'CDS':'ADA'}_重点议题榜.csv">下载分项CSV →</a><a href="量化口径_v0.1.md">核对评分规则 →</a></div><h2 style="margin-top:20px">逐项依据与待补</h2>${rows.map(r=>`<div id="${r.id}">${details(r,tab)}</div>`).join('')}`;document.querySelector('#scenario').onchange=e=>{scenario=e.target.value;render()}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;scenario='默认';render()});document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a){const target=document.getElementById(a.getAttribute('href').slice(1));if(target)target.querySelector('details').open=true}});render();
</script></body></html>'''
